rule.definition:
/*IF true is returned this means validations are met */
if(
  /*SAVE EXIT*/
  ri!button = #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3155714",
  and(
    /* First NAME */
    #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!nomination.firstName),
    /* JOB FUNCTION */
    #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!nomination.functionName),
    /* CURRENT PML */
    #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!nomination.currentPML),
    /* EMAIL */
    #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!nomination.nonUsEmail),    
    /*JOB FUNCTION OTHER*/
    if(
      property(ri!nomination,"functionName",null) = #"_a-0000e6c1-137f-8000-9bf9-011c48011c48_3565630",
      #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!nomination.otherFunctionName),
      true
    ),
    /*Type of Position */
    #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!nomination.subPositionTypeId),
    /*LAST NAME */
    #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!nomination.lastName),
    /*JOB FAMILY  */
    #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!nomination.levelName),
    /*JOB DESCRITPION  */
    #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!nomination.jobDescription),
    /*MEMEBER FIRM PARTNER OR EQUIVALENT*/
    #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!nomination.ismemberFirmpartner)
  ),
  if(
    /*SUBMIT */
    ri!button = #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3155707",
    and(
      /* First NAME */
      #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!nomination.firstName),
      /* JOB FUNCTION */
      #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!nomination.functionName),
      /* CURRENT PML */
      #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!nomination.currentPML),
      /* EMAIL */
      #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!nomination.nonUsEmail),    
      /*JOB FUNCTION OTHER*/
      if(
        property(ri!nomination,"functionName",null) = #"_a-0000e6c1-137f-8000-9bf9-011c48011c48_3565630",
        #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!nomination.otherFunctionName),
        true
      ),
      /*Type of Position */
      #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!nomination.subPositionTypeId),
      /*LAST NAME */
      #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!nomination.lastName),
      /*JOB FAMILY  */
      #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!nomination.levelName),
      /*JOB DESCRITPION  */
      #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!nomination.jobDescription),
      /*MEMEBER FIRM PARTNER OR EQUIVALENT*/
      #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!nomination.ismemberFirmpartner),
      /*YEARS WITH FIRM*/
      #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!nomination.yearsWithFirm),
      /*ORIGINATING COUNTRY */
      #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!nomination.origMemberFirmCountry),
      /*ORIGINATING HOME OFFICE */
      #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!nomination.originatingHomeOffice),
      /*RETURNING COUNTRY */
      #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!nomination.returningMemberFirmCountry),
      /*RETURNING HOME OFFICE */
      #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!nomination.returnHomeOffice),
      /*PCAOB */
      #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!nomination.isPcaob),
      /*ISA */
      #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!nomination.isIsa),
      /*IFRS */
      #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!nomination.isIfrsb),
      /*US GAAP */
      #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!nomination.isUsGaapb),
      /*AICPA */
      #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!nomination.isAicpa),
      /*PCAOB LEVEL */
      if(
        property(ri!nomination,"isPcaob",false) = true,
        #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!nomination.pcaobLevel),
        true
      ),
      /*ISA LEVEL */
      if(
        property(ri!nomination,"isIsa",false) = true,
        #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!nomination.isaLevel),
        true
      ),
      /*IFRS LEVEL */
      if(
        property(ri!nomination,"isIfrsb",false) = true,
        #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!nomination.ifrsbLevel),
        true
      ),
      /*US GAAP LEVEL */
      if(
        property(ri!nomination,"isUsGaapb",false) = true,
        #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!nomination.usGaapbLevel),
        true
      ),
      /*AICPA LEVEL */
      if(
        property(ri!nomination,"isAicpa",false) = true,
        #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!nomination.aicpaLevel),
        true
      ),
      /*ANTICIPATED START DATE */
      #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!nomination.anticipatedStartDate),
      /*ANTICIPATED END DATE */
      #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!nomination.anticipatedEndDate),
      /*CPA LICENSE */
      #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!nomination.hasCpaLicense),
      /*STATES*/
      if(
        property(ri!nomination,"hasCpaLicense",null) = true,
        #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!nomination.statesForCpaLicence),
        true
      ),
      /*IS LANGUAGES */
      #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!nomination.isOtherLanguage),
      /*OTHER LANGUAGES*/
      if(
        property(ri!nomination,"isOtherLanguage",null) = true,
        #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!nomination.languageOtherThanEng),
        true
      ),
      /*DOCUMENTS*/
      if(
        or(
          #"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(ri!taskStatus),
          contains(
            {
              #"_a-0000e72d-09a6-8000-9c0e-011c48011c48_4570051",
              #"_a-0000e72d-09a6-8000-9c0e-011c48011c48_4570066",
            },
            ri!taskStatus
          )
        ),
        ri!hasDocument,
        true
      )
    ),
    false
  )
)
